package com.desktodo.app;
import org.json.*;import java.util.*;import java.time.*;
/** Shared id-based completion registers; undo is a timestamped tombstone. */
final class SharedData {
 static JSONObject capture(JSONObject previous,JSONArray ledger,JSONArray active,JSONObject cfg,long now)throws Exception{JSONObject out=DeskModel.copy(previous);for(String kind:new String[]{"completions","habits","dates"})if(out.optJSONObject(kind)==null)out.put(kind,new JSONObject());JSONObject done=out.getJSONObject("completions");for(int i=0;i<ledger.length();i++){JSONObject r=ledger.getJSONObject(i);String id=r.getString("id");long at=Instant.parse(r.getString("completedAt")).toEpochMilli();JSONObject old=done.optJSONObject(id);if(old!=null&&old.optLong("stamp")>=at&&(old.optBoolean("deleted")||old.optLong("completedAt")>at))continue;if(old==null||old.optBoolean("deleted")||old.optLong("completedAt")!=at)done.put(id,new JSONObject().put("stamp",now).put("completedAt",at).put("deleted",false));}for(int i=0;i<active.length();i++){String id=active.getJSONObject(i).getString("id");JSONObject old=done.optJSONObject(id);if(old!=null&&!old.optBoolean("deleted"))done.put(id,new JSONObject().put("stamp",now).put("completedAt",old.optLong("completedAt")).put("deleted",true));}for(String kind:new String[]{"habits","dates"}){JSONArray source=cfg.optJSONArray(kind);JSONObject old=out.getJSONObject(kind);Set<String> seen=new HashSet<>();for(int i=0;source!=null&&i<source.length();i++){JSONObject r=source.getJSONObject(i);String id=r.getString("id");seen.add(id);JSONObject prior=old.optJSONObject(id),next=prior==null?new JSONObject():DeskModel.copy(prior);next.put("title",r.getString("title")).put("deleted",false);if(kind.equals("dates"))next.put("date",r.getString("date"));else{JSONObject days=next.optJSONObject("days");if(days==null)days=new JSONObject();Set<String> checked=new HashSet<>();JSONArray values=r.optJSONArray("days");for(int n=0;values!=null&&n<values.length();n++)checked.add(values.getString(n));Set<String> all=new HashSet<>(checked);for(Iterator<String> it=days.keys();it.hasNext();)all.add(it.next());for(String day:all){boolean yes=checked.contains(day);JSONObject mark=days.optJSONObject(day);if(mark==null||mark.optBoolean("checked")!=yes)days.put(day,new JSONObject().put("stamp",now).put("checked",yes));}List<String> keys=new ArrayList<>();for(Iterator<String> it=days.keys();it.hasNext();)keys.add(it.next());Collections.sort(keys);for(int n=0;n<keys.size()-56;n++)days.remove(keys.get(n));next.put("days",days);}if(prior==null||!equalPayload(prior,next))next.put("stamp",now);old.put(id,next);}for(Iterator<String> it=old.keys();it.hasNext();){String id=it.next();JSONObject e=old.getJSONObject(id);if(!seen.contains(id)&&!e.optBoolean("deleted"))e.put("deleted",true).put("stamp",now);}}return out;}
 static boolean equalPayload(JSONObject a,JSONObject b)throws Exception{JSONObject x=DeskModel.copy(a),y=DeskModel.copy(b);x.remove("stamp");y.remove("stamp");return ScreenSync.same(x,y);}
 static JSONArray ledger(JSONObject shared)throws Exception{JSONArray out=new JSONArray();JSONObject entries=shared.optJSONObject("completions");if(entries!=null)for(Iterator<String> it=entries.keys();it.hasNext();){String id=it.next();JSONObject e=entries.getJSONObject(id);if(!e.optBoolean("deleted"))out.put(new JSONObject().put("id",id).put("recordType","completed").put("completedAt",Instant.ofEpochMilli(e.getLong("completedAt")).toString()));}return out;}
 static JSONObject apply(JSONObject cfg,JSONObject shared)throws Exception{JSONObject out=DeskModel.copy(cfg);for(String kind:new String[]{"habits","dates"}){JSONArray values=new JSONArray();JSONObject entries=shared.optJSONObject(kind);if(entries!=null)for(Iterator<String> it=entries.keys();it.hasNext();){String id=it.next();JSONObject e=entries.getJSONObject(id);if(e.optBoolean("deleted"))continue;JSONObject v=new JSONObject().put("id",id).put("title",e.getString("title"));if(kind.equals("dates"))v.put("date",e.getString("date"));else{JSONArray days=new JSONArray();JSONObject marks=e.optJSONObject("days");if(marks!=null)for(Iterator<String> d=marks.keys();d.hasNext();){String day=d.next();if(marks.getJSONObject(day).optBoolean("checked"))days.put(day);}v.put("days",days);}values.put(v);}out.put(kind,values);}return out;}
}
